descriptor.templateCss:
.scada-view-container {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 14px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #64B856;
  padding: 12px 18px 10px 18px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
  overflow: hidden;
}

.scada-header-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 32px;
  margin-bottom: 4px;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.scada-logo-icon {
  font-size: 20px;
}

.scada-title {
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.6px;
  color: #f1f5f9;
}

.scada-subtitle {
  font-size: 11px;
  color: #64748b;
  margin-top: 1px;
}

.scada-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 3px 12px;
  border-radius: 20px;
  letter-spacing: 0.5px;
  white-space: nowrap;
}

.scada-badge.offgrid {
  color: #06b6d4;
  border: 1.5px solid #06b6d4;
  background: rgba(6, 182, 212, 0.1);
}

.scada-canvas-wrapper {
  width: 100%;
  flex: 1;
  min-height: 250px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.scada-svg-canvas {
  width: 100%;
  height: 100%;
  display: block;
}

/* ESTILOS DE LÍNEAS DE FLUJO Y ANIMACIONES MARCHING ANTS */
.flow-line {
  stroke-width: 3.5;
  stroke-linecap: round;
}

.flow-solar {
  stroke: #f7d048;
  stroke-dasharray: 8 6;
  animation: flowForward 1s linear infinite;
}

.flow-bess-charging {
  stroke: #64B856;
  stroke-dasharray: 8 6;
  animation: flowForward 1.2s linear infinite;
}

.flow-bess-discharging {
  stroke: #f59e0b;
  stroke-dasharray: 8 6;
  animation: flowReverse 1.2s linear infinite;
}

.flow-pcs {
  stroke: #38bdf8;
  stroke-dasharray: 8 6;
  animation: flowForward 0.9s linear infinite;
}

.flow-load {
  stroke: #62c3f5;
  stroke-dasharray: 8 6;
  animation: flowForward 0.8s linear infinite;
}

.flow-dg-standby {
  stroke: #475569;
  stroke-width: 2.2;
  stroke-dasharray: 5 5;
}

.flow-dg-running {
  stroke: #a855f7;
  stroke-dasharray: 8 6;
  animation: flowReverse 1s linear infinite;
}

@keyframes flowForward {
  from { stroke-dashoffset: 28; }
  to { stroke-dashoffset: 0; }
}

@keyframes flowReverse {
  from { stroke-dashoffset: 0; }
  to { stroke-dashoffset: 28; }
}

/* BADGES DE POTENCIA INSTANTÁNEA EN LÍNEA (ESTILO PILL SLEEK) */
.flow-badge-bg {
  fill: #070e08;
  transition: all 0.3s ease;
  filter: drop-shadow(0 2px 4px rgba(0,0,0,0.5));
}

.flow-badge-text {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.3px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  user-select: none;
}

/* BARRA COLECTORA AC GLOW */
.ac-busbar {
  stroke: #38bdf8;
  stroke-width: 7;
  stroke-linecap: round;
  filter: drop-shadow(0 0 8px rgba(56, 189, 248, 0.6));
}

/* NODOS SCADA */
.scada-node-box {
  fill: #101c13;
  stroke: rgba(100, 184, 86, 0.18);
  stroke-width: 1;
  filter: drop-shadow(0 4px 8px rgba(0,0,0,0.4));
}

.n-header { font-size: 10.5px; font-weight: 800; fill: #94a3b8; letter-spacing: 0.3px; }
.n-mini-tag { font-size: 10px; font-weight: 700; fill: #38bdf8; }
.n-value { font-size: 26px; font-weight: 800; line-height: 1; }
.n-sub { font-size: 11px; fill: #64748b; font-weight: 500; }
.n-sub-highlight { font-size: 11px; font-weight: 700; }
.n-sub-bold { font-size: 11px; font-weight: 700; }
.n-status { font-size: 10px; font-weight: 700; letter-spacing: 0.3px; }
.n-pcs-item { font-size: 11px; fill: #cbd5e1; font-weight: 500; }

.scada-footer-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: #64748b;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding-top: 8px;
  padding-right: 175px;
  margin-top: 4px;
}

descriptor.controllerScript:
self.onInit = function() {
  self.onDataUpdated();
};

self.onDataUpdated = function() {
  var data = self.ctx.data;
  // Valores por defecto
  var solarKw = 94.0, solarKwh = 2258.3;
  var soc = 62.0, bessKw = 213.4, vdc = 779.1, idc = 395.3, estadoBess = 'CARGANDO';
  var loadKw = 295.1, loadKwh = 508.0;
  var dgKw = 0.0, dgEstado = 'STANDBY';
  var freqHz = 59.99, vac = 220.0;
  var pcs1 = 102.9, pcs2 = 96.5, pcs3 = 95.7;

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var rawVal = item.data[item.data.length - 1][1];
        var v = parseFloat(rawVal);
        var strV = String(rawVal);
        var k = (item.dataKey.name || item.dataKey.label || '').toLowerCase();

        if (k.indexOf('generacion_solar') !== -1 || k === 'potencia_solar' || k.indexOf('solar_kw') !== -1) solarKw = v;
        else if (k.indexOf('epv_hoy') !== -1 || k.indexOf('energia_solar_hoy') !== -1) solarKwh = v;
        else if (k === 'soc_promedio' || k === 'bess_soc' || k === 'soc') soc = v;
        else if (k.indexOf('potencia_bess') !== -1) bessKw = v;
        else if (k.indexOf('estado_bess') !== -1) estadoBess = strV.toUpperCase();
        else if (k.indexOf('vbat') !== -1) vdc = v;
        else if (k.indexOf('ibat_total') !== -1 || k === 'ibat') idc = v;
        else if (k.indexOf('demanda') !== -1 || k.indexOf('carga_kw') !== -1 || k === 'potencia_demanda') loadKw = v;
        else if (k.indexOf('eload_hoy') !== -1 || k.indexOf('energia_carga_hoy') !== -1) loadKwh = v;
        else if (k.indexOf('carga_pcs1') !== -1 || k.indexOf('pac_pcs1') !== -1) pcs1 = Math.abs(v);
        else if (k.indexOf('carga_pcs2') !== -1 || k.indexOf('pac_pcs2') !== -1) pcs2 = Math.abs(v);
        else if (k.indexOf('carga_pcs3') !== -1 || k.indexOf('pac_pcs3') !== -1) pcs3 = Math.abs(v);
        else if (k.indexOf('dg_potencia') !== -1) dgKw = v;
        else if (k.indexOf('estado_generador') !== -1) dgEstado = strV.toUpperCase();
        else if (k.indexOf('frecuencia') !== -1) freqHz = v;
        else if (k.indexOf('tension_fase') !== -1 || k === 'vacu') {
          vac = v > 180 ? v : Math.round(v * 1.732 * 10) / 10;
        }
      }
    }
  }

  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (!container) return;

  // Protección física para BESS: si la telemetría envía suma raw de pac (-815 kW),
  // calcular la potencia real de descarga del BESS por balance físico en bus DC
  var pBatDisp = Math.abs(bessKw);
  if (pBatDisp > loadKw * 1.5 && loadKw > 20) {
    pBatDisp = Math.abs(Math.round(((loadKw / 0.96) - solarKw) * 10) / 10);
  }

  // Filtrado de valor centinela 65535 Modbus en energía de carga
  if (loadKwh >= 60000) {
    loadKwh = Math.round((loadKwh % 65535) * 10) / 10;
  }

  var isCharging = estadoBess.indexOf('CARG') !== -1 || (bessKw > 2.0 && estadoBess.indexOf('DESC') === -1);

  // ── 1. ACTUALIZAR BADGES DE FLUJO INSTANTÁNEO EN LÍNEA (kW) ──
  // A. Línea Solar
  var elFlowSol = container.querySelector('#flow-val-solar');
  if (elFlowSol) elFlowSol.textContent = solarKw.toFixed(1) + ' kW';

  // B. Línea BESS
  var elFlowBess = container.querySelector('#flow-val-bess');
  var elFlowBgBess = container.querySelector('#flow-bg-bess');
  if (elFlowBess) {
    var bessPrefix = isCharging ? '▲ ' : '▼ ';
    elFlowBess.textContent = bessPrefix + pBatDisp.toFixed(1) + ' kW';
    elFlowBess.setAttribute('fill', isCharging ? '#64B856' : '#f7d048');
  }
  if (elFlowBgBess) {
    elFlowBgBess.setAttribute('stroke', isCharging ? '#64B856' : '#f7d048');
  }

  // C. Línea Inversores PCS -> Bus AC
  var elFlowPcs = container.querySelector('#flow-val-pcs');
  if (elFlowPcs) elFlowPcs.textContent = loadKw.toFixed(1) + ' kW';

  // D. Línea Bus AC -> Carga
  var elFlowLoad = container.querySelector('#flow-val-load');
  if (elFlowLoad) elFlowLoad.textContent = loadKw.toFixed(1) + ' kW';

  // E. Línea Diésel DG -> ATS
  var isDgRunning = dgKw > 0.5 || dgEstado.indexOf('OPER') !== -1 || dgEstado.indexOf('RUN') !== -1;
  var elFlowDg = container.querySelector('#flow-val-dg');
  var elFlowBgDg = container.querySelector('#flow-bg-dg');
  if (elFlowDg) {
    elFlowDg.textContent = dgKw.toFixed(1) + ' kW';
    elFlowDg.setAttribute('fill', isDgRunning ? '#a855f7' : '#94a3b8');
  }
  if (elFlowBgDg) {
    elFlowBgDg.setAttribute('stroke', isDgRunning ? '#a855f7' : '#64748b');
  }

  // ── 2. ACTUALIZAR LÍNEAS DE ANIMACIÓN DE FLUJO ──
  var pathBess = container.querySelector('#path-bess');
  var bessTopline = container.querySelector('#svg-bess-topline');
  if (pathBess) {
    pathBess.className.baseVal = 'flow-line ' + (isCharging ? 'flow-bess-charging' : 'flow-bess-discharging');
  }
  if (bessTopline) bessTopline.setAttribute('stroke', isCharging ? '#64B856' : '#f7d048');

  var pathDg = container.querySelector('#path-dg');
  if (pathDg) {
    pathDg.className.baseVal = 'flow-line ' + (isDgRunning ? 'flow-dg-running' : 'flow-dg-standby');
  }

  // ── 3. ACTUALIZAR TARJETAS DE EQUIPO (ENERGÍA ACUMULADA Y ESTADO) ──
  // Nodo 1: Solar
  var elSolKw = container.querySelector('#svg-solar-kw');
  if (elSolKw) elSolKw.innerHTML = solarKw.toFixed(1) + ' <tspan font-size="13" fill="#94a3b8">kW</tspan>';
  var elSolKwh = container.querySelector('#svg-solar-kwh');
  if (elSolKwh) elSolKwh.textContent = 'Hoy: ' + solarKwh.toFixed(1) + ' kWh';

  // Nodo 2: BESS
  var elSoc = container.querySelector('#svg-bess-soc');
  if (elSoc) elSoc.innerHTML = Math.round(soc) + ' <tspan font-size="13" fill="#94a3b8">% SOC</tspan>';
  var elBessKw = container.querySelector('#svg-bess-kw');
  if (elBessKw) {
    var arrow = isCharging ? '▲' : '▼';
    var text = isCharging ? ' (CARGANDO)' : ' (DESCARGANDO)';
    elBessKw.textContent = arrow + ' ' + pBatDisp.toFixed(1) + ' kW' + text;
    elBessKw.setAttribute('fill', isCharging ? '#64B856' : '#f7d048');
  }
  var elBessDc = container.querySelector('#svg-bess-dc');
  if (elBessDc) {
    var idcSign = idc >= 0 ? '+' : '';
    elBessDc.textContent = 'Bus DC: ' + vdc.toFixed(1) + ' V | ' + idcSign + idc.toFixed(1) + ' A';
  }

  // Nodo 3: Inversores PCS
  var setPcs = function(id, val) {
    var e = container.querySelector(id);
    if (e) e.textContent = Math.abs(val).toFixed(1) + ' kW';
  };
  setPcs('#svg-pcs1-kw', pcs1);
  setPcs('#svg-pcs2-kw', pcs2);
  setPcs('#svg-pcs3-kw', pcs3);

  // Nodo 4: Carga
  var elLdKw = container.querySelector('#svg-load-kw');
  if (elLdKw) elLdKw.innerHTML = loadKw.toFixed(1) + ' <tspan font-size="13" fill="#94a3b8">kW</tspan>';
  var elLdKwh = container.querySelector('#svg-load-kwh');
  if (elLdKwh) elLdKwh.textContent = 'Hoy: ' + loadKwh.toFixed(1) + ' kWh';

  // Nodo 5: Diésel y ATS
  var elDgKw = container.querySelector('#svg-dg-kw');
  if (elDgKw) {
    elDgKw.innerHTML = dgKw.toFixed(1) + ' <tspan font-size="13" fill="#94a3b8">kW</tspan>';
    elDgKw.setAttribute('fill', isDgRunning ? '#a855f7' : '#64748b');
  }
  var elAts = container.querySelector('#svg-ats-state');
  var elAtsSw = container.querySelector('#svg-ats-switch');
  var elDgSt = container.querySelector('#svg-dg-status');
  var dgTopline = container.querySelector('#svg-dg-topline');
  if (elAts) {
    elAts.textContent = isDgRunning ? 'ATS: CERRADO (EN CARGA)' : 'ATS: DESCONECTADO';
    elAts.setAttribute('fill', isDgRunning ? '#a855f7' : '#64748b');
  }
  if (elAtsSw) {
    elAtsSw.setAttribute('fill', isDgRunning ? '#a855f7' : '#64748b');
  }
  if (elDgSt) {
    elDgSt.textContent = isDgRunning ? '● EN GENERACIÓN' : '○ STANDBY AUTOMÁTICO';
    elDgSt.setAttribute('fill', isDgRunning ? '#22c55e' : '#94a3b8');
  }
  if (dgTopline) dgTopline.setAttribute('stroke', isDgRunning ? '#a855f7' : '#64748b');

  // Barra Colectora AC
  var elBus = container.querySelector('#svg-bus-telemetry');
  if (elBus) elBus.textContent = vac.toFixed(1) + ' V | ' + freqHz.toFixed(2) + ' Hz';

  // ── 4. BALANCE DE PLANTA EN MICRORRED AUTÓNOMA ──
  var elBal = container.querySelector('#footer-balance-text');
  if (elBal) {
    if (isDgRunning) {
      elBal.textContent = 'RESPALDO DIÉSEL ACTIVO (DG: +' + dgKw.toFixed(1) + ' kW | BESS: ' + pBatDisp.toFixed(1) + ' kW)';
      elBal.style.color = '#a855f7';
    } else if (solarKw >= loadKw) {
      var surplus = solarKw - loadKw;
      elBal.textContent = 'SUPERÁVIT SOLAR (+' + surplus.toFixed(1) + ' kW NETO) → BESS EN CARGA';
      elBal.style.color = '#64B856';
    } else {
      var deficitSolar = loadKw - solarKw;
      elBal.textContent = 'AUTÓNOMO EN EQUILIBRIO (Déficit Solar -' + deficitSolar.toFixed(1) + ' kW cubierto por BESS: ' + pBatDisp.toFixed(1) + ' kW)';
      elBal.style.color = '#64B856';
    }
  }
};

self.onDestroy = function() {};
